use std::collections::BinaryHeap;
use std::cmp::Reverse;

let n = grid.len();
let mut heap = BinaryHeap::new();
let mut visited = vec![vec![vec![false; k as usize + 1]; n]; n];

// Initialize the heap with all possible starting points
for i in 0..n {
    for j in 0..n {
        heap.push(Reverse((vec![grid[i][j]], i, j, 1)));
    }
}

// Directions for moving in the grid (up, down, left, right)
let directions = [(-1, 0), (1, 0), (0, -1), (0, 1)];

while let Some(Reverse((path, x, y, len))) = heap.pop() {
    if len == k {
        return path;
    }

    for &(dx, dy) in &directions {
        let nx = x as isize + dx;
        let ny = y as isize + dy;

        if nx >= 0 && nx < n as isize && ny >= 0 && ny < n as isize {
            let nx = nx as usize;
            let ny = ny as usize;

            if !visited[nx][ny][len as usize] {
                visited[nx][ny][len as usize] = true;
                let mut new_path = path.clone();
                new_path.push(grid[nx][ny]);
                heap.push(Reverse((new_path, nx, ny, len + 1)));
            }
        }
    }
}

